class Solution {
    long long C2(long long m) {
        if (m < 2) return 0;
        return m * (m - 1) / 2;
    }
public:
    long long distributeCandies(int n, int limit) {
        long long N = n, L = limit;
        return C2(N + 2) - 3 * C2(N - L + 1) + 3 * C2(N - 2 * L) - C2(N - 3 * L - 1);
    }
};
